  if (!Number.isFinite(min)) return []
  const first = min - ((new Date(min).getUTCDay() - weekStartsOn + 7) % 7) * DAY_MS
  const last = max + ((weekStartsOn + 6 - new Date(max).getUTCDay() + 7) % 7) * DAY_MS
