  for (let time = first; time <= last; time += 7 * DAY_MS) {
    weeks.push(
      Array.from({ length: 7 }, (_, index) => {
        const current = time + index * DAY_MS,
          date = toISO(current),
          inRange = current >= min && current <= max
        return { date, inRange, count: inRange ? (counts.get(date) ?? 0) : 0 }
      }),
    )
  }
