export function barsFromList(list: readonly SeriesListItem[]): BarSeries[] {
  return list.map((item) => {
    const { label, rest } = splitLabel(item.text)
    return {
      label: label || item.text,
      values: numbers(rest),
      size: item.strong ? 'lg' : undefined,
    }
  })
}

